import{_ as a,o as e,c as s,a2 as i}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"전쟁과 공성","description":"","frontmatter":{},"headers":[],"relativePath":"rules/Warfare-and-Sieges.md","filePath":"rules/Warfare-and-Sieges.md"}'),d={name:"rules/Warfare-and-Sieges.md"};function l(n,t,r,h,o,p){return e(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="전쟁과-공성" tabindex="-1">전쟁과 공성 <a class="header-anchor" href="#전쟁과-공성" aria-label="Permalink to &quot;전쟁과 공성&quot;">​</a></h1><p><img src="https://github.com/islee23520/seoul-kenshi/blob/main/docs/assets/wiki/isometric-warfare-sieges.svg?raw=true" alt="공성 접근로와 퇴로의 아이소 전장"></p><p>공성 시 접근로, 보급, 퇴로를 4방향 시야와 공간으로 계획합니다.</p><p>전쟁은 병력 수 비교가 아니라 접근로, 보급, 사기, 퇴로와 점령 후 유지 능력을 둘러싼 연속 과정입니다. 아래 수치는 <strong>설계 가정</strong>입니다.</p><h2 id="입력과-출력" tabindex="-1">입력과 출력 <a class="header-anchor" href="#입력과-출력" aria-label="Permalink to &quot;입력과 출력&quot;">​</a></h2><table tabindex="0"><thead><tr><th>입력</th><th style="text-align:right;">범위·기본값</th><th>출력</th></tr></thead><tbody><tr><td>전력 <code>S</code></td><td style="text-align:right;">0~100, 기본 100</td><td>현재 전투 가능 인원·장비</td></tr><tr><td>결속 <code>C</code></td><td style="text-align:right;">0~100, 기본 70</td><td>대형 유지와 철수 통제</td></tr><tr><td>보급일 <code>D</code></td><td style="text-align:right;">0~6, 기본 3</td><td>작전 지속 가능 기간</td></tr><tr><td>피로 <code>F</code></td><td style="text-align:right;">0~100, 기본 0</td><td>전투 효율·패주 손실</td></tr><tr><td>접근 용량 <code>A</code></td><td style="text-align:right;">1~3, 기본 2</td><td>동시에 전력을 투입할 파티 수</td></tr><tr><td>방어 엄폐 <code>V</code></td><td style="text-align:right;">0~30, 기본 10</td><td>지형·차단막·고저차 효과</td></tr><tr><td>압박 <code>P</code>·돌파 <code>B</code></td><td style="text-align:right;">0~100, 기본 0</td><td>봉쇄와 진입 진행도</td></tr></tbody></table><h2 id="계산-규칙" tabindex="-1">계산 규칙 <a class="header-anchor" href="#계산-규칙" aria-label="Permalink to &quot;계산 규칙&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>피로계수 = clamp(1 - F/200, 0.5, 1)</span></span>
<span class="line"><span>적재계수 = clamp(1 - max(0, 적재율-80)/100, 0.8, 1)</span></span>
<span class="line"><span>압박증가 = clamp(6 + floor((공격작전력-수비작전력)/20) - 고립, 1, 12)</span></span>
<span class="line"><span>패주손실 = clamp(15 + 5*고립 + floor(F/10), 15, 35)</span></span>
<span class="line"><span>주둔요구 = clamp(20 + 10*적대접근로수 + floor(5*과확장), 20, 80)</span></span></code></pre></div><p><code>고립</code>은 <a href="/world/Logistics-and-Infrastructure.html">물류</a>에 정의된 고립 단계(정상 0, 부분 봉쇄 1, 완전 차단 2)이고, <code>과확장</code>도 같은 문서의 공유 0~2 척도를 그대로 사용합니다. 전투는 시작 시 확정된 전투 컨텍스트만 사용하며, 종료 결과는 <code>ResultId</code>로 한 번만 캠페인에 반영합니다.</p><h2 id="기본-수치" tabindex="-1">기본 수치 <a class="header-anchor" href="#기본-수치" aria-label="Permalink to &quot;기본 수치&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th style="text-align:right;">기본값</th><th style="text-align:right;">최소</th><th style="text-align:right;">최대</th></tr></thead><tbody><tr><td>보급일</td><td style="text-align:right;">3일</td><td style="text-align:right;">0일</td><td style="text-align:right;">6일</td></tr><tr><td>접근 용량</td><td style="text-align:right;">2파티</td><td style="text-align:right;">1</td><td style="text-align:right;">3</td></tr><tr><td>위험 추가 손실</td><td style="text-align:right;">0</td><td style="text-align:right;">0</td><td style="text-align:right;">4</td></tr><tr><td>철수 피로</td><td style="text-align:right;">+15</td><td style="text-align:right;">0</td><td style="text-align:right;">100</td></tr><tr><td>압박 일일 증가</td><td style="text-align:right;">6</td><td style="text-align:right;">1</td><td style="text-align:right;">12</td></tr><tr><td>점령 직후 치안</td><td style="text-align:right;">20</td><td style="text-align:right;">0</td><td style="text-align:right;">100</td></tr></tbody></table><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">stateDiagram-v2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [*] --&gt; 접근</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  접근 --&gt; 교전: 공격 명령</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  접근 --&gt; 봉쇄: 압박 작전</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  봉쇄 --&gt; 돌파: P&gt;=40, B 누적</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  교전 --&gt; 질서철수: 합법 퇴로 선택</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  교전 --&gt; 패주: 결속 붕괴</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  돌파 --&gt; 점령: 목표 확보</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  점령 --&gt; 안정화: 주둔·수리·협상</span></span></code></pre></div><h2 id="경계-상황" tabindex="-1">경계 상황 <a class="header-anchor" href="#경계-상황" aria-label="Permalink to &quot;경계 상황&quot;">​</a></h2><ul><li>탄약과 식량을 묶은 보급일이 0이면 전투 계수는 0.60이며 다음 무보급 공성일을 지속할 수 없습니다.</li><li>고립은 압박 증가를 낮추고 철수·패주 손실을 키우며 점령지 수리를 막습니다.</li><li>퇴로가 봉쇄되면 질서 철수 대신 긴급 탈출, 항복 또는 패주만 가능하며, 퇴로 그래프 검사(<code>LegalFallback</code>)를 통과하지 못하면 패주손실을 적용합니다.</li><li>점령 승리는 시설 복구와 주민 협력을 자동 부여하지 않습니다.</li><li>동시 공격은 접근 용량만큼만 완전 전력을 쓰고 나머지는 예비·지원으로 정산합니다.</li></ul><h2 id="계산-예시" tabindex="-1">계산 예시 <a class="header-anchor" href="#계산-예시" aria-label="Permalink to &quot;계산 예시&quot;">​</a></h2><p>공격 작전력 90, 수비 작전력 78, 고립 0이면 <code>압박증가=clamp(6+floor(12/20),1,12)=6</code>입니다. 공격대 피로 40이면 피로계수는 <code>clamp(1-0.2,0.5,1)=0.8</code>입니다. 같은 공격대가 고립 2, 피로 70으로 패주하면 <code>패주손실=clamp(15+10+7,15,35)=32</code>가 되어 보급로를 지키지 않은 대가가 전투 후에도 남습니다.</p>`,16)])])}const y=a(d,[["render",l]]);export{c as __pageData,y as default};
